class LineageValidationError(DomainError):
    """A malformed lineage query (``direction`` / ``max_depth``).

    Renders with the same ``validation_error`` code and issue-shaped details
    as request-body validation failures.
    """

    status_code = 422
    code = "validation_error"
    message = "Request payload failed validation."

    def __init__(self, issues: list[dict]):
        super().__init__(details={"issues": issues})


def _validation_body(exc: RequestValidationError) -> dict:
    # Keep the payload small, stable, and JSON-safe: loc/msg/type per error.
    issues = [
        {
            "loc": [str(part) for part in error.get("loc", [])],
            "msg": error.get("msg", ""),
            "type": error.get("type", ""),
        }
        for error in exc.errors()
    ]
    return {
        "error": {
            "code": "validation_error",
            "message": "Request payload failed validation.",
            "details": {"issues": issues},
        }
    }


def register_exception_handlers(app) -> None:
    @app.exception_handler(DomainError)
    async def _handle_domain_error(_: Request, exc: DomainError) -> JSONResponse:
        return exc.to_response()

    @app.exception_handler(RequestValidationError)
    async def _handle_validation_error(
        _: Request, exc: RequestValidationError
    ) -> JSONResponse:
        return JSONResponse(status_code=422, content=_validation_body(exc))

    @app.exception_handler(StarletteHTTPException)
    async def _handle_http_error(
        _: Request, exc: StarletteHTTPException
    ) -> JSONResponse:
        return JSONResponse(
            status_code=exc.status_code,
            content={
                "error": {
                    "code": {
                        404: "not_found",
                        405: "method_not_allowed",
                        409: "conflict",
                    }.get(exc.status_code, "http_error"),
                    "message": str(exc.detail),
                }
            },
        )

    @app.exception_handler(Exception)
    async def _handle_unexpected(_: Request, exc: Exception) -> JSONResponse:
        # Never leak internals (or content-bearing payloads) to clients.
        return JSONResponse(
            status_code=500,
            content={"error": {"code": "internal_error", "message": "Internal error."}},
        )

        next_cursor=next_cursor,
    )


def _reject_any_query_param(request: Request) -> None:
    """422 on any query parameter (known, unknown, blank, or repeated).

    The exchange-style read routes take no query parameters: any parameter
    at all is a 422 rather than silently ignored.
    """
    raw = request.query_params
    if raw:
        field = sorted(set(raw))[0]
        raise _query_validation_error(
            field, f"unknown query parameter: {field}", "value_error.unknown"
        )


def _exchange_snapshot_response(
    evidence_bundle_id: str, session: Session
) -> EvidenceBundleExchangeResponse:
    # Strictly read-only: the snapshot writes no resource and no audit event.
    bundle, claim, content, attestations = service.get_evidence_bundle_exchange(
        session, evidence_bundle_id
    )
    return EvidenceBundleExchangeResponse(
        content=ContentResponse.model_validate(content),
        claim=ClaimResponse.model_validate(claim),
        evidence_bundle=_bundle_response(bundle),
        attestations=[_attestation_response(item) for item in attestations],

    # the five single-target fields -- never a signature, attestation
    # payload, claim payload, or content bytes.
    return _compact_json_response(response, status.HTTP_200_OK)


def _compact_json_response(model, status_code: int) -> Response:
    """Serialize a response model as compact UTF-8 JSON + one newline.

    Numbers render as integers (never ``-0`` or a non-finite value), exactly
    as on the other compact-wire routes.
    """
    body = (
        json.dumps(
            model.model_dump(mode="json"),
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
        + "\n"
    ).encode("utf-8")
    return Response(
        content=body, status_code=status_code, media_type="application/json"
    )


